58	
59	DHTEntryPointNameResolveCommand::DHTEntryPointNameResolveCommand(
60	    cuid_t cuid, DownloadEngine* e, int family,
61	    const std::vector<std::pair<std::string, uint16_t>>& entryPoints)
62	    : Command{cuid},
63	      e_{e},
64	#ifdef ENABLE_ASYNC_DNS
65	      asyncNameResolverMan_{make_unique<AsyncNameResolverMan>()},
66	#endif // ENABLE_ASYNC_DNS
67	      taskQueue_{nullptr},
68	      taskFactory_{nullptr},
69	      routingTable_{nullptr},
70	      entryPoints_(std::begin(entryPoints), std::end(entryPoints)),
71	      family_{family},
72	      numSuccess_{0},
73	      bootstrapEnabled_{false}
74	{
75	#ifdef ENABLE_ASYNC_DNS
76	  configureAsyncNameResolverMan(asyncNameResolverMan_.get(), e_->getOption());
77	  asyncNameResolverMan_->setIPv4(family_ == AF_INET);
78	  asyncNameResolverMan_->setIPv6(family_ == AF_INET6);
79	#endif // ENABLE_ASYNC_DNS
80	}
81	
82	DHTEntryPointNameResolveCommand::~DHTEntryPointNameResolveCommand()
83	{
84	#ifdef ENABLE_ASYNC_DNS
85	  asyncNameResolverMan_->disableNameResolverCheck(e_, this);
86	#endif // ENABLE_ASYNC_DNS
87	}
88	
89	bool DHTEntryPointNameResolveCommand::execute()
90	{
91	  if (e_->getRequestGroupMan()->downloadFinished() || e_->isHaltRequested()) {
92	    return true;
93	  }
94	  try {
95	#ifdef ENABLE_ASYNC_DNS
96	    if (e_->getOption()->getAsBool(PREF_ASYNC_DNS)) {
97	      while (!entryPoints_.empty()) {
98	        std::string hostname = entryPoints_.front().first;
99	        std::vector<std::string> res;
100	        int rv = resolveHostname(res, hostname);
101	        if (rv == 0) {
102	          e_->addCommand(std::unique_ptr<Command>(this));
103	          return false;
104	        }
105	        else {
106	          if (rv == 1) {
107	            ++numSuccess_;
108	            std::pair<std::string, uint16_t> p(res.front(),
109	                                               entryPoints_.front().second);
110	            addPingTask(p);
111	          }
112	          asyncNameResolverMan_->reset(e_, this);
113	        }
114	        entryPoints_.pop_front();
115	      }
116	    }
117	    else
118	#endif // ENABLE_ASYNC_DNS
119	    {
120	      NameResolver res;
121	      res.setSocktype(SOCK_DGRAM);
122	      res.setFamily(family_);
123	      while (!entryPoints_.empty()) {
124	        std::string hostname = entryPoints_.front().first;
125	        try {
126	          std::vector<std::string> addrs;
127	          res.resolve(addrs, hostname);
128	
129	          ++numSuccess_;
130	          std::pair<std::string, uint16_t> p(addrs.front(),
131	                                             entryPoints_.front().second);
132	          addPingTask(p);
133	        }
134	        catch (RecoverableException& e) {
135	          A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
136	        }
137	        entryPoints_.pop_front();
138	      }
139	    }
140	    if (bootstrapEnabled_ && numSuccess_) {
141	      taskQueue_->addPeriodicTask1(
142	          taskFactory_->createNodeLookupTask(localNode_->getID()));
143	      taskQueue_->addPeriodicTask1(taskFactory_->createBucketRefreshTask());
144	    }
145	  }
146	  catch (RecoverableException& e) {
147	    A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
148	  }
149	  return true;
150	}
151	
152	void DHTEntryPointNameResolveCommand::addPingTask(
153	    const std::pair<std::string, uint16_t>& addr)
154	{
155	  auto entryNode = std::make_shared<DHTNode>();
156	  entryNode->setIPAddress(addr.first);
157	  entryNode->setPort(addr.second);
158	
159	  taskQueue_->addPeriodicTask1(taskFactory_->createPingTask(entryNode, 10));
160	}
161	
162	#ifdef ENABLE_ASYNC_DNS
163	
164	int DHTEntryPointNameResolveCommand::resolveHostname(
165	    std::vector<std::string>& res, const std::string& hostname)
166	{
167	  if (!asyncNameResolverMan_->started()) {
168	    asyncNameResolverMan_->startAsync(hostname, e_, this);
169	  }
170	
171	  switch (asyncNameResolverMan_->getStatus()) {
172	  case -1:
173	    A2_LOG_INFO(fmt(MSG_NAME_RESOLUTION_FAILED, getCuid(), hostname.c_str(),
174	                    asyncNameResolverMan_->getLastError().c_str()));
175	    return -1;
176	  case 0:
177	    return 0;
178	  case 1:
179	    asyncNameResolverMan_->getResolvedAddress(res);
180	    if (res.empty()) {
181	      A2_LOG_INFO(fmt(MSG_NAME_RESOLUTION_FAILED, getCuid(), hostname.c_str(),
182	                      "No address returned"));
183	      return -1;
184	    }
185	    else {
186	      A2_LOG_INFO(fmt(MSG_NAME_RESOLUTION_COMPLETE, getCuid(), hostname.c_str(),
187	                      res.front().c_str()));
188	      return 1;
189	    }
190	  }
191	
192	  // Unreachable
193	  return 0;
194	}
195	
196	#endif // ENABLE_ASYNC_DNS
