79	DHTSetup::DHTSetup() = default;
80	
81	DHTSetup::~DHTSetup() = default;
82	
83	std::pair<std::vector<std::unique_ptr<Command>>,
84	          std::vector<std::unique_ptr<Command>>>
85	DHTSetup::setup(DownloadEngine* e, int family)
86	{
87	  std::vector<std::unique_ptr<Command>> tempCommands;
88	  std::vector<std::unique_ptr<Command>> tempRoutineCommands;
89	  if ((family != AF_INET && family != AF_INET6) ||
90	      (family == AF_INET && DHTRegistry::isInitialized()) ||
91	      (family == AF_INET6 && DHTRegistry::isInitialized6())) {
92	    return {};
93	  }
94	  try {
95	    // load routing table and localnode id here
96	    std::shared_ptr<DHTNode> localNode;
97	
98	    DHTRoutingTableDeserializer deserializer(family);
99	    const std::string& dhtFile = e->getOption()->get(
100	        family == AF_INET ? PREF_DHT_FILE_PATH : PREF_DHT_FILE_PATH6);
101	    try {
102	      deserializer.deserialize(dhtFile);
103	      localNode = deserializer.getLocalNode();
104	    }
105	    catch (RecoverableException& e) {
106	      A2_LOG_ERROR_EX(
107	          fmt("Exception caught while loading DHT routing table from %s",
108	              dhtFile.c_str()),
109	          e);
110	    }
111	    if (!localNode) {
112	      localNode = std::make_shared<DHTNode>();
113	    }
114	
115	    uint16_t port;
116	    auto connection = make_unique<DHTConnectionImpl>(family);
117	    {
118	      port = e->getBtRegistry()->getUdpPort();
119	      const std::string& addr = e->getOption()->get(
120	          family == AF_INET ? PREF_DHT_LISTEN_ADDR : PREF_DHT_LISTEN_ADDR6);
121	      // If UDP port is already used, use the same port
122	      // number. Normally IPv4 port is available, then IPv6 port is
123	      // (especially for port >= 1024). We don't loose much by doing
124	      // this. We did the same thing in TCP socket. See BtSetup.cc.
125	      bool rv;
126	      if (port == 0) {
127	        auto sgl =
128	            util::parseIntSegments(e->getOption()->get(PREF_DHT_LISTEN_PORT));
129	        sgl.normalize();
130	        rv = connection->bind(port, addr, sgl);
131	      }
132	      else {
133	        rv = connection->bind(port, addr);
134	      }
135	      if (!rv) {
136	        throw DL_ABORT_EX("Error occurred while binding UDP port for DHT");
137	      }
138	      localNode->setPort(port);
139	    }
140	    A2_LOG_DEBUG(fmt("Initialized local node ID=%s",
141	                     util::toHex(localNode->getID(), DHT_ID_LENGTH).c_str()));
142	    auto tracker = std::make_shared<DHTMessageTracker>();
143	    auto routingTable = make_unique<DHTRoutingTable>(localNode);
144	    auto factory = make_unique<DHTMessageFactoryImpl>(family);
145	    auto dispatcher = make_unique<DHTMessageDispatcherImpl>(tracker);
146	    auto receiver = make_unique<DHTMessageReceiver>(tracker);
147	    auto taskQueue = make_unique<DHTTaskQueueImpl>();
148	    auto taskFactory = make_unique<DHTTaskFactoryImpl>();
149	    auto peerAnnounceStorage = make_unique<DHTPeerAnnounceStorage>();
150	    auto tokenTracker = make_unique<DHTTokenTracker>();
151	    // For now, UDPTrackerClient was enabled along with DHT
152	    auto udpTrackerClient = std::make_shared<UDPTrackerClient>();
153	    const auto messageTimeout =
154	        e->getOption()->getAsInt(PREF_DHT_MESSAGE_TIMEOUT);
155	    // wiring up
156	    tracker->setRoutingTable(routingTable.get());
157	    tracker->setMessageFactory(factory.get());
158	
159	    dispatcher->setTimeout(std::chrono::seconds(messageTimeout));
160	
161	    receiver->setMessageFactory(factory.get());
162	    receiver->setRoutingTable(routingTable.get());
163	
164	    taskFactory->setLocalNode(localNode);
165	    taskFactory->setRoutingTable(routingTable.get());
166	    taskFactory->setMessageDispatcher(dispatcher.get());
167	    taskFactory->setMessageFactory(factory.get());
168	    taskFactory->setTaskQueue(taskQueue.get());
169	    taskFactory->setTimeout(std::chrono::seconds(messageTimeout));
170	
171	    routingTable->setTaskQueue(taskQueue.get());
172	    routingTable->setTaskFactory(taskFactory.get());
173	
174	    peerAnnounceStorage->setTaskQueue(taskQueue.get());
175	    peerAnnounceStorage->setTaskFactory(taskFactory.get());
176	
177	    factory->setRoutingTable(routingTable.get());
178	    factory->setConnection(connection.get());
179	    factory->setMessageDispatcher(dispatcher.get());
180	    factory->setPeerAnnounceStorage(peerAnnounceStorage.get());
181	    factory->setTokenTracker(tokenTracker.get());
182	    factory->setLocalNode(localNode);
183	    factory->setBtRegistry(e->getBtRegistry().get());
184	
185	    PrefPtr prefEntryPointHost = family == AF_INET ? PREF_DHT_ENTRY_POINT_HOST
186	                                                   : PREF_DHT_ENTRY_POINT_HOST6;
187	    if (!e->getOption()->get(prefEntryPointHost).empty()) {
188	      {
189	        PrefPtr prefEntryPointPort = family == AF_INET
190	                                         ? PREF_DHT_ENTRY_POINT_PORT
191	                                         : PREF_DHT_ENTRY_POINT_PORT6;
192	        std::pair<std::string, uint16_t> addr(
193	            e->getOption()->get(prefEntryPointHost),
194	            e->getOption()->getAsInt(prefEntryPointPort));
195	        std::vector<std::pair<std::string, uint16_t>> entryPoints;
196	        entryPoints.push_back(addr);
197	        auto command = make_unique<DHTEntryPointNameResolveCommand>(
198	            e->newCUID(), e, family, entryPoints);
199	        command->setBootstrapEnabled(true);
200	        command->setTaskQueue(taskQueue.get());
201	        command->setTaskFactory(taskFactory.get());
202	        command->setRoutingTable(routingTable.get());
203	        command->setLocalNode(localNode);
204	        tempCommands.push_back(std::move(command));
205	      }
206	    }
207	    else {
208	      A2_LOG_INFO("No DHT entry point specified.");
209	    }
210	    {
211	      auto command = make_unique<DHTInteractionCommand>(e->newCUID(), e);
212	      command->setMessageDispatcher(dispatcher.get());
213	      command->setMessageReceiver(receiver.get());
214	      command->setTaskQueue(taskQueue.get());
215	      command->setReadCheckSocket(connection->getSocket());
216	      command->setConnection(std::move(connection));
217	      command->setUDPTrackerClient(udpTrackerClient);
218	      tempRoutineCommands.push_back(std::move(command));
219	    }
220	    {
221	      auto command = make_unique<DHTTokenUpdateCommand>(
222	          e->newCUID(), e, DHT_TOKEN_UPDATE_INTERVAL);
223	      command->setTokenTracker(tokenTracker.get());
224	      tempCommands.push_back(std::move(command));
225	    }
226	    {
227	      auto command = make_unique<DHTBucketRefreshCommand>(
228	          e->newCUID(), e, DHT_BUCKET_REFRESH_CHECK_INTERVAL);
229	      command->setTaskQueue(taskQueue.get());
230	      command->setRoutingTable(routingTable.get());
231	      command->setTaskFactory(taskFactory.get());
232	      tempCommands.push_back(std::move(command));
233	    }
234	    {
235	      auto command = make_unique<DHTPeerAnnounceCommand>(
236	          e->newCUID(), e, DHT_PEER_ANNOUNCE_CHECK_INTERVAL);
237	      command->setPeerAnnounceStorage(peerAnnounceStorage.get());
238	      tempCommands.push_back(std::move(command));
239	    }
240	    {
241	      auto command =
242	          make_unique<DHTAutoSaveCommand>(e->newCUID(), e, family, 30_min);
243	      command->setLocalNode(localNode);
244	      command->setRoutingTable(routingTable.get());
245	      tempCommands.push_back(std::move(command));
246	    }
247	    // add deserialized nodes to routing table
248	    auto& desnodes = deserializer.getNodes();
249	    for (auto& node : desnodes) {
250	      routingTable->addNode(node);
251	    }
252	    if (!desnodes.empty()) {
253	      auto task = std::static_pointer_cast<DHTBucketRefreshTask>(
254	          taskFactory->createBucketRefreshTask());
255	      task->setForceRefresh(true);
256	      taskQueue->addPeriodicTask1(task);
257	    }
258	    // assign them into DHTRegistry
259	    if (family == AF_INET) {
260	      DHTRegistry::getMutableData().localNode = localNode;
261	      DHTRegistry::getMutableData().routingTable = std::move(routingTable);
262	      DHTRegistry::getMutableData().taskQueue = std::move(taskQueue);
263	      DHTRegistry::getMutableData().taskFactory = std::move(taskFactory);
264	      DHTRegistry::getMutableData().peerAnnounceStorage =
265	          std::move(peerAnnounceStorage);
266	      DHTRegistry::getMutableData().tokenTracker = std::move(tokenTracker);
267	      DHTRegistry::getMutableData().messageDispatcher = std::move(dispatcher);
268	      DHTRegistry::getMutableData().messageReceiver = std::move(receiver);
269	      DHTRegistry::getMutableData().messageFactory = std::move(factory);
270	      e->getBtRegistry()->setUDPTrackerClient(udpTrackerClient);
271	      DHTRegistry::setInitialized(true);
272	    }
273	    else {
274	      DHTRegistry::getMutableData6().localNode = localNode;
275	      DHTRegistry::getMutableData6().routingTable = std::move(routingTable);
276	      DHTRegistry::getMutableData6().taskQueue = std::move(taskQueue);
277	      DHTRegistry::getMutableData6().taskFactory = std::move(taskFactory);
278	      DHTRegistry::getMutableData6().peerAnnounceStorage =
279	          std::move(peerAnnounceStorage);
280	      DHTRegistry::getMutableData6().tokenTracker = std::move(tokenTracker);
281	      DHTRegistry::getMutableData6().messageDispatcher = std::move(dispatcher);
282	      DHTRegistry::getMutableData6().messageReceiver = std::move(receiver);
283	      DHTRegistry::getMutableData6().messageFactory = std::move(factory);
284	      DHTRegistry::setInitialized6(true);
285	    }
286	    if (e->getBtRegistry()->getUdpPort() == 0) {
287	      // We assign port last so that no exception gets in the way
288	      e->getBtRegistry()->setUdpPort(port);
289	    }
290	  }
291	  catch (RecoverableException& ex) {
292	    A2_LOG_ERROR_EX(fmt("Exception caught while initializing DHT functionality."
293	                        " DHT is disabled."),
294	                    ex);
295	    tempCommands.clear();
296	    tempRoutineCommands.clear();
297	    if (family == AF_INET) {
298	      DHTRegistry::clearData();
299	      e->getBtRegistry()->setUDPTrackerClient(
300	          std::shared_ptr<UDPTrackerClient>{});
301	    }
302	    else {
303	      DHTRegistry::clearData6();
304	    }
305	  }
306	  return std::make_pair(std::move(tempCommands),
307	                        std::move(tempRoutineCommands));
308	}
309	
