62	// handles UDP trackers as well as DHT.
63	DHTInteractionCommand::DHTInteractionCommand(cuid_t cuid, DownloadEngine* e)
64	    : Command{cuid},
65	      e_{e},
66	      dispatcher_{nullptr},
67	      receiver_{nullptr},
68	      taskQueue_{nullptr}
69	{
70	  setStatusRealtime();
71	}
