#include "Command.h"
#include "LogFactory.h"

namespace aria2 {

Command::Command(cuid_t cuid)
    : cuid_(cuid),
      status_(STATUS_INACTIVE),
      readEvent_(false),
      writeEvent_(false),
      errorEvent_(false),
      hupEvent_(false)
{
}

void Command::transitStatus()
{
  switch (status_) {
  case STATUS_REALTIME:
    break;
  default:
    status_ = STATUS_INACTIVE;
  }
}

